// Patch notes: hand-curated, newest first. Nothing appears here because a
// commit exists — an entry is written deliberately, in the player's voice,
// and several commits can share one entry. Workflow: add the entry at the top
// with the next number, cite every commit it covers (`hash`/`short` name the
// newest; `also` lists the rest), then run `npm run patches` to check the
// file against history. `n` is stable: Patch 1 is the oldest gameplay change.
export interface Patch {
  n: number; hash: string; short: string; date: string; title: string; summary: string; tags: string[];
  /** Older commits this entry also covers, newest last. */
  also?: string[];
  /** Full bullet points, only on the big overhauls. */
  details?: string[];
}

export const PATCHES: Patch[] = [
  { n: 75, hash: "60f0a50a416ac35e087e76e253be7a1725c23cf1", short: "60f0a50", date: "2026-09-23", title: "Report a bug from inside the game", summary: "Settings has a Report a bug button, in town, on the title screen and mid-delve. Write what happened in any language and the game opens a GitHub issue with everything else filled in: where you're standing, what's in front of you, your gear and your build. It also copies a screenshot of the screen to paste in.", tags: ["dungeon", "town"], also: ["943544f"], details: ["You read the whole issue on GitHub before posting, and nothing is sent until you submit it there. It needs a GitHub account.", "If your browser won't copy the screenshot (some phones), Save screenshot downloads it to attach instead.", "The dungeon stays paused while you type, and typing never moves you.", "No save change."] },
  { n: 74, hash: "a70ed5e6c9608719024601ac4f2bd2f949383165", short: "a70ed5e", date: "2026-09-22", title: "Faster start", summary: "The game starts faster, most of all on a phone: all the art now arrives in one download instead of more than three hundred small ones before the title screen could appear.", tags: ["core"] },
  { n: 73, hash: "1803549d4933f91c02cbd5443d5f5da437171fda", short: "1803549", date: "2026-09-22", title: "Gold reads the same everywhere", summary: "Gold reads the same everywhere: the HUD, the pack and the floating +gold numbers now group large sums (12,345g) like the town always did. A broken cracked wall in the Emberworks no longer leaves a mismatched patch of plain roof above it.", tags: ["core"] },
  { n: 72, hash: "e50a153ef5d2465b85ff6e10133ceec364c9685e", short: "e50a153", date: "2026-09-22", title: "Cloud saves stop asking about a save you never touched", summary: "Signing in after an update could ask you to choose between your save and another device's, even when you had not touched the save on this device since. An update that reshapes saves no longer counts as you playing: if the other device moved on and this one did not, its progress is simply taken.", tags: ["saves"] },
  { n: 71, hash: "70697c56f151925758e44f2641424d3a6a463576", short: "70697c5", date: "2026-09-22", title: "Smoother frames in the dungeon", summary: "Nothing looks or plays differently; the dungeon just does less work per frame, which matters most on a phone. Damage numbers stop making the page re-measure itself, the HUD and minimap only redraw what changed, sprites at the edge of your sight are kept instead of rebuilt on every step, and monsters looking for a path around each other check the room once per search.", tags: ["core"], also: ["7e4b4b4"] },
  { n: 70, hash: "dbefa1eb533500151f0634ccbb4e11704ffba595", short: "dbefa1e", date: "2026-09-20", title: "The stairs do not always go where stairs go", summary: "Every so often a floor below the first comes out wrong. One is upside down and full of cattle. One is in black and white, a quarter faster, and everybody is wearing a top hat. You find out by walking down.", tags: ["dungeon", "loot"], also: ["e1e0e23", "d009d74", "dbbd863"], details: ["The Forbidden Pasture: the world is upside down, turning left looks like turning right, and every monster has been replaced by cattle of its own weight class. One of them wears a rosette. Every urn is a chest and every chest is a vault.", "The Silent Picture: no colour, a piano, and everything running at five-quarters speed — including you. Every creature wears a top hat and a monocle, and whatever you are swinging is drawn as a cane.", "Nothing on either floor hits harder than its depth. The Pasture charges you for being upside down and the Picture charges you for the clock; neither charges you twice.", "Each carries a relic that exists nowhere else: the Prize Bull\u2019s Horn and the Impresario\u2019s Cane. No chest can give you one, and neither can the King.", "Also new, and found anywhere from depth 2: the Big Toe. It is a toe. It cleaves wider and staggers harder than anything else you can hold in one hand, and it has to be swung from right on top of something."] },
  { n: 69, hash: "657f52bf499d1ba411fb962a453685aa31a7792c", short: "657f52b", date: "2026-09-20", title: "Monsters stop swinging the same way twice", summary: "Every melee monster used to have exactly one rhythm, so learning a skeleton taught you the whole dungeon. They now pick from a set of attacks when they commit, and the wind-up glows in the colour of the one they chose.", tags: ["combat", "dungeon"], details: ["Seven attacks: a plain blow, a jab too fast to walk out of, a flurry of three that leaves a long opening, a thrust that reaches two tiles, a sweep that catches the sidestep, an overhead slam worth nearly two blows, and a feint whose lean stalls once to bait your guard.", "Read the glow. Pale is quick, blue reaches, orange comes round the sides, violet holds steady and is lying to you, and a red flare that grows with the monster is the one to be somewhere else for.", "Open a monster up mid-flurry \u2014 a parry will do it \u2014 and the rest of the flurry never lands.", "This is variety, not difficulty. Across seven simulated playstyles the damage you take is unchanged; you simply take it in more, smaller pieces. Twenty monsters have a set; archers, the Hoarder and the King keep what they had."] },
  { n: 68, hash: "dd6bad427e51ad528794a2c55882e98e21de669e", short: "dd6bad4", date: "2026-09-19", title: "Oaths stack, and there are more of them", summary: "Swear as many oaths as you dare. Each kept oath pays on its own (medium one inscription, hard two), and keeping every one of two or more pays one more. The stone now offers two hard and three medium oaths a day, from a pool of eight.", tags: ["town", "dungeon", "saves"], also: ["a50f8d0", "78d31d1"], details: ["Hard: Blood Price (cursed with Frailty; bring home 250 found gold), Dry Throat (the flask starts empty; reach depth 4), Duelist (no blocking, only the parry; 20 kills), Kingsbane (monsters hit harder; kill the King).", "Medium: Unbroken (gear wears twice as fast; reach depth 4 whole), Hunter (three marked elites), Silence (monsters see you less, noise carries twice as far; reach depth 3 without an alarm or Wardcry), Pilgrim (idols curse far more often; pray at three shrines).", "A broken oath loses only its own reward. With every inscription known, oaths pay renown instead. Saves carry over, including an oath already sworn.", "A reward paying several inscriptions is picked together in town and learned at once."] },
  { n: 67, hash: "c33730a0d3eeeb4ff4fad9a6f593cf3be991caae", short: "c33730a", date: "2026-09-19", title: "Fixed: cloud saves after the update", summary: "The first sign-in on the big update could refuse to upload your save and ask you to choose between it and an older cloud copy. The new save fields had changed its fingerprint and the sync mistook that for another device. Your progress now uploads as it always did; a real save from another device still asks.", tags: ["saves"] },
  { n: 66, hash: "7283d0d21e43d205eca7167ac396d7b4a082df0f", short: "7283d0d", date: "2026-09-19", title: "The Ashen Seals, and a panel on the way down", summary: "Oaths are now chosen as you descend: pressing Descend opens a panel with the Oath Stone and a way down. And once you've killed the Ashen King, the same panel offers the Ashen Seals, stackable handicaps that each pay a quarter more renown and more loot.", tags: ["town", "dungeon", "saves"], details: ["The Oath Stone moved from above the town tabs into the Descend panel. A kept oath's reward still waits in town until you choose it.", "Seal of Teeth: monsters hit 20% harder. Multitudes: 30% more monsters. Champions: elites far more often, from the first floor. The Dry Well: the flask starts two charges short. The Lightless: your light reaches less far.", "Each Seal set pays +25% renown and +15 loot find for the delve. Seals stay set until you break them. Killing the King under more Seals than ever sets a record.", "If you've already killed the King, the Seals are open to you now. Saves carry over with none set."] },
  { n: 65, hash: "b54633d4c14075bcab6adbda8d0d338dcfdef75b", short: "b54633d", date: "2026-09-19", title: "Lieutenants", summary: "From depth 2, a floor sometimes has a lieutenant that changes it while it lives. The Goblin Quartermaster's banner makes every goblin fight harder and never run; kill it and they flee, and its strongbox is yours. The Hoarder carries off any loot left lying around; kill it and it all spills back out.", tags: ["dungeon", "combat", "art"], details: ["A clue on arrival tells you a lieutenant is on the floor: goblins moving in formation, or coin scraping across stone.", "The Goblin Quartermaster only appears where there are goblins to command. While it stands, they hit 25% harder and never flee.", "The Hoarder keeps away from you and only fights when cornered. It never takes keys or flask shards.", "No save change."] },
  { n: 64, hash: "cd396f12fa0cca5807eec11b42c8f94322e34297", short: "cd396f1", date: "2026-09-19", title: "Your Shade keeps what you lost", summary: "Dying no longer throws your pack away. What you lose waits on the depth where you fell, held by your Shade, a pale version of you. Go back, kill it, and take everything back. Die again first and it's gone for good.", tags: ["dungeon", "saves"], details: ["The backpack and the coin you carried, beyond what a Soul Pouch keeps, go into a grave on the depth where you fell. Your Shade waits there on a later delve, far from the stairs, fighting with the kind of weapon you died holding.", "Kill it and the whole pack drops where it stood. Coming home without reclaiming it leaves it waiting; dying again before you do replaces it, and the old pack is lost for good.", "The town news and the results screen tell you where your Shade is. On Hardcore a death ends the save, so there's no grave.", "Saves carry over with no grave waiting."] },
  { n: 63, hash: "4b8e54c61740372b5d379fe094e1fbc4ab607aac", short: "4b8e54c", date: "2026-09-19", title: "Every floor its own law", summary: "The Ossuary's dead don't stay down unless you shatter or sanctify them. The Deep Mines' braced walls crush whatever stands beside them when you bring one down. The Vermin Burrows carry every sound further, and a broken root cache makes a lure.", tags: ["dungeon", "combat"], details: ["The Ossuary: an undead monster's remains stir a few seconds after it dies and stand back up at half health, once. A blunt killing blow shatters them, holy damage sanctifies them, and either keeps them down.", "The Deep Mines: bringing down a cracked wall drops its timbers on every monster beside it, for a crushing blow and a stagger.", "The Vermin Burrows: cracked walls, Wardcry, alarm wards and a struck chest are all heard much further away. Breaking a root cache draws whatever hears it to the cache, not to you.", "Arriving on one of these floors tells you its law. No save change."] },
  { n: 62, hash: "8c7e4cce6c615530e2fc9da45a5a177565bb51e3", short: "8c7e4cc", date: "2026-09-19", title: "The stair splits", summary: "The first time down from depth 2, the stair splits into two roads: the Mine, Frozen, Ember or Spore Road. The one you take decides depths 3 and 4, and the other is sealed. Which two are open changes each day with what's happening in Bleakmere, and the town news names them so you can prepare.", tags: ["dungeon", "town"], details: ["The Mine Road (Deep Mines): shieldbearers and the Barrow Champion; pays in metal. The Frozen Road (Frost Vault): bring fire; pays in frost shards and moonstone. The Ember Road (Emberworks): bring frost; pays in flame shards and sunstone. The Spore Road (Sporegrove): the Bog Seraph; pays in leather and crystal.", "Market events tilt the roads: an Iron Shortage or War Drums open the mines, a Harsh Winter the frozen road, a dragon sighting or the Great Forge burning the ember road, the academy's Arcane Study or a Royal Wedding the spore road.", "Press 1 or 2 to choose, or Esc to step back from the stair; it asks again next time. Depth 5 rolls its own biome as before.", "A delve already under way keeps going the old way. No save change."] },
  { n: 61, hash: "138ce9b3a1180045c36f6c3fbf4bd7a88ca9831b", short: "138ce9b", date: "2026-09-19", title: "Oaths and inscriptions", summary: "Swear an oath at the Oath Stone before you go down: Blood Price, Unbroken or Hunter, each changing a rule and asking something of the delve. Keep it and come home alive to learn an inscription, then cut it into your gear at the forge's new Inscribe bench: Riposte, Execution, Kindling, Bulwark, Retrieval or Last Flask.", tags: ["combat", "town", "saves"], also: ["1436252"], details: ["Blood Price: you start cursed with Frailty, which no font will lift. Come home with 250 gold found in the dungeon.", "Unbroken: everything you wear wears twice as fast. Reach depth 4 with nothing breaking, then come home.", "Hunter: monsters see you two tiles further, and a marked elite, one of the toughest on its floor, waits on each of depths 2, 3 and 4. Kill all three, then come home.", "A kept oath lets you choose one of three inscriptions you haven't learned; with all of them learned it pays 10 renown. A broken oath costs only the reward. The HUD shows how your oath stands.", "Inscribing costs 150 gold at the forge, one per item; inscribing again replaces it, and relics can't take one. Riposte: after a parry your next swing is free and hits \u00d71.3. Execution: finishing a reeling monster refunds double sigil cooldown. Kindling: fire on a monster below half health burns one beside it. Bulwark: a heavy blow on the shield makes your next strike hit \u00d71.5. Retrieval: called-back shafts cut what they pass through. Last Flask: with the flask empty, food and leech heal \u00d71.5.", "Saves carry over: nothing learned, nothing sworn."] },
  { n: 60, hash: "f242fb28277c3789f57348b6ce13c2d552751862", short: "f242fb2", date: "2026-09-19", title: "The Gravecaller", summary: "A hooded necromancer walks the Ossuary and the Catacombs from depth 2. It barely fights: it chants over the undead you've killed and stands them back up. Break the chant with any blow, shatter the bones with a blunt killing blow, or sanctify them with holy damage, and they stay down.", tags: ["combat", "dungeon", "art"], details: ["The Gravecaller keeps its distance and chants for two seconds over the nearest fallen undead within four tiles. The corpse glows green and stands back up at half its health. Up to three times in its life, six seconds apart.", "Any damage breaks the chant, including a thrown weapon or a reflected bolt.", "A blunt killing blow, or one that hits a quarter of the monster's health harder than needed, shatters the bones. A killing blow with holy damage, or from Threshold's consecrated ground, sanctifies them. Either way they can't be raised. The log tells you when a Gravecaller is near to care.", "Goblins, rats and other living things stay dead. A raised corpse gives nothing when it falls again.", "Floors you've already generated are untouched. No save change."] },
  { n: 59, hash: "af2e900d31a86e2603c0373490e8ca32530b2a77", short: "af2e900", date: "2026-09-19", title: "Walls that give", summary: "Some walls are cracked, and three blows from anything bring one down. A plain crack is a shortcut, a thin crack with a dull glint is an ore seam, and a faint outline in the mortar is someone's sealed cache. Every blow wears your weapon and carries through the walls to anything within six tiles.", tags: ["dungeon", "art"], also: ["b05ac72"], details: ["Any weapon breaks a cracked wall in three blows. Each blow wears it like a landed hit, and alerts monsters within six tiles, even through walls.", "Shortcuts are thin walls between passages that are a long way apart on foot. Two a floor.", "Seams spill two to four pieces of metal ore for the depth; they're commonest in the Vermin Burrows and the Deep Mines. Caches hold a hoard like a chest's, and never less than a handful of coin.", "Broken walls stay broken for the rest of the delve. The one-button tap swings at a crack in front of you.", "Floors you've already generated have no cracks. No save change."] },
  { n: 58, hash: "cf9c0ed59934e89a403406817c63fc4279e175c5", short: "cf9c0ed", date: "2026-09-19", title: "Look up. Watch the floor.", summary: "Some monsters now hide. Ceiling Crawlers cling over corridors from depth 2 and drop when you pass; spot them like traps and knock them down first. Tunnel Stalkers lie buried under earth floors as mounds, and a badly hurt Delver Mole dives and comes up behind you. Nothing hits you as it arrives: an ambush costs you position, never a free blow.", tags: ["combat", "dungeon", "art"], details: ["Ceiling Crawlers: one a floor at depths 2–3, two at 4–5, none on the first floor or the throne. Look down a corridor to spot one (\"Something clings to the ceiling ahead\"); Lantern Wick, Charlie Work and Sounding all help. Come within a tile and it lets go after a beat of falling dust.", "Half the Tunnel Stalkers on Vermin Burrows and Deep Mines floors start buried, shown as a mound of turned earth. Come close and the ground heaves.", "The Delver Mole dives once below about a third of its health, travels under the floor as a mound you can watch, and surfaces beside you, behind you if it can.", "Strike a spotted crawler or any mound on the tile in front of you to bring it out early: it reels for a second and a half and takes double damage.", "Anything that drops or surfaces waits half a second before it can start a swing, with the usual red flash.", "Floors you've already generated are untouched. No save change."] },
  { n: 57, hash: "bfbdb20e2f949e1dc48bdd47058b5e47e1d43510", short: "bfbdb20", date: "2026-09-19", title: "Elites, and a Cutpurse that earns the name", summary: "From depth 3 down, some monsters are elites: the same creature with one trait on top, glowing in the trait's colour and named on the target bar. Hasted, Ironhide, Frenzied, Vengeful and Thieving each change how the fight goes, and each pays well. And the Goblin Cutpurse now steals from your pack and runs. Kill it to get your things back.", tags: ["combat", "dungeon"], also: ["88981f1", "0a6decd", "375d02c", "26177fe"], details: ["Elites are 5% of spawns at depth 3, rising to 11% at depth 6, about one or two a floor. None on depths 1 and 2, and never the King or his guards.", "Hasted (yellow) winds up, recovers and walks much faster. Ironhide (steel) has much harder armour and more health but is slow. Frenzied (red) speeds up below half health. Vengeful (violet) bursts a moment after dying, hitting its tile and the four beside it: step away, or face it and block or parry. Monsters in the blast get hurt too. Thieving (gold) steals like the Cutpurse.", "Every elite has half again the health and pays two and a half times the gold, three times the chance of gear, and more materials.", "The Cutpurse steals when its blow gets through: one piece of gear, or half a stack. It runs glowing gold, and its target bar says what it's carrying. It panics into dead ends, now and then fumbles the loot, and drops a few coins as it runs; once it loses you it runs a little further, then hides and creeps. Kill it to get your things back; lose sight of it for 25 seconds and they're gone. Equipped gear is never at risk, and a block or a parry stops the theft. Cutpurses are a third as common as before: about one a floor on the first two depths.", "Floors you've already generated keep their monsters exactly as they were. No save change."] },
  { n: 56, hash: "0acbb1cc05fae47c312ee676a8bc855b516ac386", short: "0acbb1c", date: "2026-09-19", title: "The flask takes draughts", summary: "Flask infusions now change what a sip does instead of adding a stat for six seconds you couldn't feel. Hide heals more, cloth brings your breath back, wood makes the sip quicker, metal blunts the next blow, bone readies a staggering strike, and fire, frost, holy and shadow gems kindle your weapon. The forge shows each one's exact effect, and the flask on your HUD takes its colour.", tags: ["combat", "town", "saves"], details: ["Thick (hide): +4 to +12 points of healing. Breath (cloth): refills stamina, costing 10 points at tier 1 down to 2 at tier 5. Quick (wood): the sip takes 0.40s down to 0.20s instead of 0.5s.", "Iron (metal): the next blow within 12s is reduced by up to 10–35% of your max health. Marrow (bone): the next strike you land within 6s deals x1.3 to x2 and staggers anything but the King. Kindled (gems): the gem's element or leech on your weapon for 8s, at twice its forge strength.", "Wood's old Speed bonus never reached your swing and Emerald's loot find went nowhere; both are gone with the old system. Jade, Crystal, Moonstone, Emerald and Wardstone can no longer be infused: if one was in your flask, it's back in your stash.", "Each sip names its draught in the log, and a bar across the top of the flask drains while an Iron, Marrow or Kindled effect is waiting to be used."] },
  { n: 55, hash: "0a8a539a3b4c282f5dc708f2645e02aca34ab9ef", short: "0a8a539", date: "2026-09-19", title: "Hardcore: one life", summary: "A third difficulty on the new-save card. Hardcore is Hard in every number, from monsters and traps to drops and the loot curve, but you get one life. Die once and the hero is gone for good: the save stays on its slot as a headstone you can rename or delete, never continue. It is chosen when a save begins and can never be changed.", tags: ["core", "saves"] },
  { n: 54, hash: "e9178f97244483cc531e931c8042bc9d0bb98f1b", short: "e9178f9", date: "2026-09-19", title: "Testing a chest has a price", summary: "Hitting a mimic no longer hurts it. The blow only wakes it, and it rises at full health, just as in Dark Souls. Hitting an honest chest is no longer free either: every blow breaks something inside, and the clang brings whatever is nearby. Read the lid, or pay to be sure. And once a chest is empty, one blow smashes it out of your way.", tags: ["art", "combat", "dungeon"], also: ["108ab74", "5d20b4a"], details: ["A struck mimic takes no damage from the blow that wakes it, and it still cannot grab you.", "Every blow on an honest chest breaks one thing inside, most precious first: gems, valuables, scrolls, flasks and blueprints, then crafting materials, then dents in the gear, and finally a quarter of the coin. Blunt and two-handed weapons have a 55% chance to break a second thing. Opening it lists what you lost. One blow costs about a quarter of a chest's worth.", "Any chest strike clangs: enemies within seven tiles, even through walls, are alerted to where you stand.", "An opened chest breaks in one blow, quietly, and no longer blocks its tile. Any loot left on it stays put.", "Existing floors follow the new rules; no save changes."] },
  { n: 53, hash: "72eefa5b58614be90377a553c29fa7cae60da2fc", short: "72eefa5", date: "2026-09-18", title: "Mimics bite like they mean it", summary: "Open a mimic and it grabs you. You are held, unable to guard, drink or parry, and it bites down hard; only armour softens it, and it can kill. The old habit saves you: hit the chest first. An honest chest turns your blow aside and stays shut, while a mimic takes the hit and rises up to fight.", tags: ["combat", "dungeon"], details: ["The grab holds you for about a second, then bites once for two and a half times a mimic's normal blow before armour. It spits you out and gives you a moment to stand before its next swing.", "Striking an honest chest leaves it undamaged and shut. Your weapon takes a little wear, half a landed blow.", "On touch screens, tap the action button to open a chest and hold it to strike instead.", "Existing floors follow the new rules; no save changes."] },
  { n: 52, hash: "bdbad49b4674f31071a69d08e150d72320073340", short: "bdbad49", date: "2026-09-16", title: "Dumplings, a bigger pack, and a forge that shows its lessons", summary: "Floor food now looks like food: gyoza, pizza slices and chicken thighs. Your pack is back to 16 slots, the forge shows how close each weapon recipe is to its next salvage lesson, and the flask's charge count is easy to read at a glance.", tags: ["art", "dungeon", "town"], also: ["9d1cc23", "4eb1c27", "ae853e5", "fc71b5a", "ee7ddef", "4a2bad0"], details: ["Food has its own sprites, one dish per size so the value reads before the prompt: a gyoza heals 10%, a pepperoni slice 12.5%, a chicken thigh 15%. Food past its prime now greys to a mouldy olive over its last minute and a half instead of darkening all at once.", "The base backpack is 16 slots again, up from 12. More material families, more monsters and larger floors made 12 tight from the first floor. Pack Mule still adds 4 per level; your pack grows the next time you are in town.", "Weapon recipes in the forge show a pip for every salvage the next rank needs, lit as you bank them. In the salvage grid, weapons that will teach you carry a teal tag, gold when that salvage completes the rank, and the tooltip shows your progress before and after.", "Materials you hold none of can no longer be picked in the forge. They stay on show, tooltip and all, so you can still see what they would do.", "The flask shows how many charges are left as one large number above the dregs bar, instead of a cramped 3/3 that ran into the bottle. The maximum is in the tooltip, and an empty flask greys out with a red 0."] },
  { n: 51, hash: "39295d675ca9183c4c15329a87aef6d5b806ca6d", short: "39295d6", date: "2026-09-16", title: "The flask, floor food, and two panic scrolls", summary: "Potions are gone: healing is a refillable flask you sip mid-fight at your own risk, monsters drop food you eat where it falls, and two dear scrolls — Flash and Backstep — answer wind-ups and bad positioning. Old saves keep everything: stashed draughts turn back into gold, Supply Crate into renown.", tags: ["combat", "dungeon", "saves", "town"], also: ["a435e8f", "6b4c25e"], details: ["Flask: 3 charges refilling every delve, 30% a sip over a 0.5s commitment with your guard down — a blow mid-sip lands unblocked and the heal still lands. Shards at depths 3 and 5 and the first King kill raise it to 6; the merchant tempers potency to 50%; fonts and satisfied idols add a charge, stones never do.", "Overheal feeds dregs: at half your health in waste it becomes a charge. The forge infuses one stash material for 6s a sip at 10 points of healing — metal guards, wood quickens, bone hits, cloth catches your breath, gems speak their catalyst, and Fight Milk is always on. Only in town.", "Morsels: scrap, cut and heart from the dead, 10–15% a bite over a 1.2s chew a hit can knock away. A loot pile on the same tile is searched first, and the loot window offers the food too. Shown on the map, rotting in 240s, and rats that reach them first eat them and grow. Loot find does not touch them.", "Flash Scroll (210g) blinds what faces you — 3s and the swing cancelled mid-wind-up, nothing on the King — with the brightest wash in the game. Backstep Scroll (160g) puts you where you stood 2 seconds ago, throne included. Both burn whether they land or not.", "Gamepad B sips the flask; Y still casts the sigil."] },  { n: 50, hash: "559adc21c905961b5019c739d8ca1090468488c2", short: "559adc2", date: "2026-09-16", title: "Two supports, every material family", summary: "Every forge recipe now takes a required support and an optional second support. Both can use metal, wood, hide, cloth or bone, so mix their bonuses or double down on one family while the item's main material stays true to its form.", tags: ["town", "combat"], details: ["Every recipe has two secondary material slots. The first keeps its existing quantity; the second is optional and costs one unit.", "Both support slots show the full metal, wood, hide, cloth and bone ladders. Cloth is now visible and usable throughout the forge, and materials are grouped by family for easier comparison.", "Main-material rules stay specific: clubs still need wood or bone bodies and swords still need metal blades. A wooden club can now add metal reinforcement and a linen wrap.", "Mix families or repeat one material when enough is owned. Both supports grant their full family and elemental bonuses once, while catalysts remain separate and keep the existing rarity and affix rules.", "Rings and pendants gain a one-unit required support; a pendant still requires its gem. The picker counts materials reserved by every slot before allowing the craft.", "Both supports appear on the finished tooltip, survive saving and each have their own salvage chance. Existing gear keeps its original single support; save revision 20 is additive.", "The forge fits the expanded choices on desktop and phone without horizontal overflow." ] },
  { n: 49, hash: "2307a12236ab93ea0637197a998d4c7c8f593bdc", short: "2307a12", date: "2026-09-16", title: "Materials with purpose, legendary bones with bite", summary: "The market now orders crafting materials white, green, blue, purple, then gold, with matching tiers across every family. Metal reinforces, wood quickens, hide toughens, cloth sustains, and bone hits harder. Rare materials keep their elemental character, while the deepest tiers bring much bigger bonuses: Titan Bone grants +20 Attack.", tags: ["town", "combat"], details: ["Every structural family follows the same tier colors: white, green, blue, purple and gold. Market rows follow that order, and headings and tooltips explain what each family adds.", "Family bonuses from tier 1 to 5: bone +1/3/6/12/20 Attack; metal +1/2/4/7/12 Defense; wood +1/2/4/7/10 Speed; hide +3/6/12/24/40 Health; cloth +3/6/10/18/30 Stamina. Primary and secondary slots each apply their material bonus once.", "Special materials keep elemental power on top: Silver +3 Holy, Moonsilver +6 Frost, Star Iron +10 Shadow, Dragon Scale +10 Fire, and Shadow Silk +7 Shadow. These stack with catalysts and affixes.", "Titan Bone makes a real difference even without mastery: an Iron Dagger at recipe rank 1 and smith level 0 previews at 28 Attack with Titan Bone, compared with 8 using Timber.", "Corrected colors do not make basic supplies scarce. Structural merchant targets are 40 for tiers 1–2 and 14 for tier 3; material drops use consistent tier weights across families. Depth gates and the slow tier-4/5 shipment schedule remain.", "Existing gear adopts the new material bonuses. Recipes, mastery and saves carry over; recipe costs, catalyst effects and blueprint rates stay unchanged. Other mixed material bonuses such as Luck, Loot Find and Spell Focus give way to the family roles."]},
  { n: 48, hash: "e01892d0dc2820b1957cb0c766228fb1014aad04", short: "e01892d", date: "2026-09-16", title: "Learn from broken blades, earn the better steel", summary: "The forge has more ways to grow: blueprints are spread through the dungeon, secret chests always hold one, and salvaging an unidentified weapon teaches its recipe. Wood, hide, cloth and bone gain the missing steps to the deepest materials, while the merchant brings late supplies slowly. On Hard, early treasure leaves room for Common gear and Rare rewards build gradually. Powerful catalysts stay in the depths where they belong, and Appraiser II no longer takes away salvage mastery.", tags: ["dungeon", "town"], also: ["ab0562d", "bd9d038"], details: ["Blueprints drop one at a time from urns, chests, vaults and enemies; every secret chest guarantees one. Plans follow your depth, favour recipes you have not learned, and favour deeper weapon plans more as you descend. Early plans leave the pool three floors after their debut; depth-four and later plans remain available.", "Salvage matching unidentified melee or thrown weapons to unlock and improve their recipe: 4 salvages to unlock, then 5, 6, 7 and 8 for ranks 2–5. The forge shows your progress, and studying a blueprint keeps the salvage progress you have earned. Crafted gear, armour and manually identified weapons do not teach mastery. Appraiser II preserves that progress source on newly auto-identified Uncommon and Rare drops.", "Nine materials complete the structural ladders: Deep Yew, Starwood, Troll Hide, Wool, Astral Silk, Dense Bone, Fossil Bone, Wyrm Bone and Titan Bone. Your existing recipes, gear and mastery carry over.", "Late merchant supplies arrive in small shipments. Tier-four stock needs depth 5 and day 6, then adds one every three days; tier five needs depth 6 and day 18, then adds one every six days. Shelf caps start at one and rise to two on days 12 and 30 respectively. Both depth and day requirements must be met.", "Hard vaults and secrets still guarantee gear, but early Uncommon and later Rare bonuses are now chances that grow with depth. Their second piece uses ordinary rarity rolls. Normal keeps its previous rarity guarantees, and the King keeps his promised rewards.", "No more late-game gems from an empty depth-one pool. Premature monster catalysts become Crystal Shards from depth 2 until their proper material gate opens; early iron, leather and spider silk rewards remain. Salvaging newly found gear respects the floor it came from, so a lucky item-level roll cannot unlock deeper catalysts.", "Blueprint rates, mastery thresholds and the slow merchant schedule are preserved in this balance pass. Fewer enchanted early drops also mean fewer weapons eligible for salvage mastery. Already identified weapons in old saves cannot be recognised retroactively as Appraiser finds."]},
  { n: 47, hash: "f4051c19ab1325de8c97faa5e5dda5967d5004b8", short: "f4051c1", date: "2026-09-16", title: "Be not afraid (it is a frog), and turn up the dark", summary: "Something new sings in the Sporegrove: the Bog Seraph, a champion-tier frog elite haunting depths 3–5 — 145 health of halo and choir that hits like a vault guardian, soft to slash like all soft bodies, and paying rich for the trouble. Watch the gape: the open mouth is the tell. And for the rest of us playing at 1am on a dimmed screen, Settings grows a Display slider — drag until the left square is barely visible and the dungeon lifts to meet your eyes. Display only: no extra light radius, no easier fights, stored on this device.", tags: ["art", "combat", "core", "dungeon"], also: ["21ba762"] },
  { n: 46, hash: "4e0a34321ce714b0bd199505a8a8201fe4630c51", short: "4e0a343", date: "2026-09-15", title: "Gold sinks, five shrine flavours, and gear that breaks for real", summary: "Coin is tighter and every coin has somewhere to go: chests, urns and loose piles pay less while vaults and secrets still pay full, and the forge takes its steady cut — repairs cost half a piece's worth plus its tier, because gear now wears twice as fast and broken gear fights on at 15% of its strength with no guard and no cleave. Shrines come more often and never leave you dry for long, their blessings hit harder, and two new altars take stranger offerings: the red one drinks half your health for gold, the ember one gives you a fight for one.", tags: ["combat", "dungeon", "town"], also: ["41b3ce2", "8b73cb3", "831b807", "a12ca49", "bc1a036"], details: ["Chests pay 8–18 per depth (was 10–22), urns 5 + 2 per depth (was 6 + 3), loose piles 2–4 per depth (was 2–5). Vaults, secrets, enemy drops and contracts pay exactly what they did.", "Repairs are the rent: half a piece's value plus a floor by tier (4g at the bottom, 50g at the top), pro-rated to what is missing. Weapons wear 2 a landed blow, shields 2 a block, armour 2 an unblocked hit, and every third swing at air costs 1.", "Breaking is rare if you listen and scary if you do not: gear warns once at a quarter gone, then goes at 15% of its stats with no guard behind it and no cleave in front of it. A new Brittle curse wears everything one faster, which is what makes finding a blue font urgent.", "Shrines answer on 55% of floors (was 45%) with a promise: at least one across depths 1–3, at least two across 4–6. Blessings scale with the depth you kneel at — Fortune finds more, Fury hits 30% harder, Warding grows, and Vitality buys a fifth more heart — while curses bite deeper to match, and the idol keeps a kinder 65/35.", "The offering stone takes up to three offerings and gets thirstier each time: 75% dearer than the last, and a quarter of the time it takes the coin and answers with silence.", "The Sanguine Altar pays 40 + 30 a depth plus what you bled for half your current health — never your last point, it refuses that. The Shrine of Strife is free to challenge and answers with 2 + half your depth in enemies already coming, plus 60 + 40 a depth when the last marked one falls. One trial at a time. Old saves keep everything."] },
  { n: 45, hash: "514d04b1ae841ab6b6d1ccaa2337dd5e1a43a651", short: "514d04b", date: "2026-09-15", title: "Bigger delves, hungrier dark, and fog that locks behind you", summary: "Every floor grows eight tiles a side with four more rooms, deeper floors pack roughly a third more monsters, and one secret is guaranteed with a second that gets likelier the deeper you go. The throne room seals behind you with fog the moment you step in — no bleeding the King through the doorway, no slipping out until he falls.", tags: ["art", "combat", "dungeon"], also: ["8347a7c", "89ef5b9", "418fc28"], details: ["Every depth expands 39 to 59 tiles a side instead of 31 to 51, with room targets up from 9 to 13 plus depth, so the larger bounds also hold more playable space — over a fifth more open ground at every depth.", "Enemies scale steeper with depth, 1.2 to 1.6 slope plus denser rooms, for roughly 30-40 percent more bodies deep while depth 1 stays readable.", "One secret room is guaranteed every floor; a second gets a low roll that grows with depth, 20 percent on depth 1 to 45 percent on depth 6, so searching pays deeper without flooding the start.", "The throne entrance is a boss fog gate with its own fog-over-iron art and a purple automap dot. Step inside with the King alive and it slams and locks behind you; only his death thins the fog and stands the way out open. Old saves are recognised by position.", "While he lives the throne is a combat boundary: sight, swings, chips, bolts, thrown shafts and reflected hits do not cross it either way, so there is no fighting him through the crack. Recall scrolls and town portals smother inside — the way out is through him.", "Loot and gold are untouched: generation moved, drop tables did not."] },
  { n: 44, hash: "c133f7e0f76cdc9b7713117335f26134a8117a71", short: "c133f7e", date: "2026-09-15", title: "The foundry breathes, the vault freezes, and the Burrows dig back", summary: "The Emberworks glows through split mortar, molten stone and iron grates, with soot-dark walls between the heat. The Frost Vault gets glazed rock underfoot and icicles overhead. Eight familiar creatures have learned to live in fire or frost, and the Burrows have a Delver Mole that guards its face with digging claws. Go around it.", tags: ["art", "combat", "dungeon"], details: ["Soot-black brick, split mortar, pooled heat and furnace grates give the Emberworks four distinct walls, with a pulsing glow.", "Five frost walls, two rock-and-ice floors, a frozen roof and clustered icicles. The hanging ice is scenery, not a trap.", "Scorched Bones, Cinder Guards, Emberbacks and Slagborn in the foundry; Rimebound, Hoarfrost Bats, Frozen Wretches and Glacier Goblins in the vault. Same base stats and timing, new elemental strengths and weaknesses.", "Delver Moles guard from the front, and root caches replace Burrows urns. Smash the roots; flank the claws.", "Existing saved floors keep their residents and props. Newly generated floors gain the new content."]},
  { n: 43, hash: "a8a3f7a29fa9acb3d37f4091ed35688fac1668f8", short: "a8a3f7a", date: "2026-09-14", title: "Resume your delve, trust the forge, keep the guild's share", summary: "Loading a mid-delve save puts you back in the dungeon; reloading no longer grants a free trip to the stash, market or forge. Ordinary reloads no longer trigger false cloud-save conflicts. The Forge badge counts recipes you have enough blueprints to unlock or upgrade. Market quantities distinguish your stash from merchant stock, quest counts cover all accepted deliveries, and Sell spare valuables keeps the guild's share safe.", tags: ["saves", "town"], also: ["2a3c4a6", "f6e34a4"] },
  { n: 42, hash: "9c9928816e4c8cce2a63f6a0ac4f56d190a0b120", short: "9c99288", date: "2026-09-14", title: "Two hands, thrown steel, and five sigils", summary: "Three two-handers take both hands and spill a quarter of every blow into the rank behind the thing you hit. Knives, axes and javelins ride a belt slot of their own, thrown with T and called home by holding R. And five sigils wait at the forge bench to be inscribed and attuned, one at a time, cast with G or C. Every held weapon, shield, hand and icon is redrawn to match.", tags: ["art", "audio", "combat", "dungeon", "town"], also: ["4617b87", "9607f15", "c61d71b", "8793ad1", "ad6d9fe", "05fbed6", "1d8f31e", "2f27634", "33e80e2", "dff4554", "e972901", "00ade98", "4f1612c", "7108de2", "68c2a8a", "7fc3da0", "1ea6a20", "1877497", "735d2ee", "79148e3", "8717fa5", "de46fda", "e3378db"], details: ["Halberd, Great Maul and Greatsword need both hands: the shield is stowed where the weapon came from, and the swap is refused rather than eating it if there is no room. Every swing cleaves 25% into all eight tiles around the target, staggers, and counts two guard chips. Blocking with one is 20%; parrying is unchanged. They hit hardest and weigh most, and a maul alone sits on the encumbered line.", "Throwing Knives, Axes and Javelins live on a belt slot, never the weapon slot, and a two-hander does not displace them. Stock is finite per delve and lands where it stops; walk over a shaft to collect it, or hold R to call them home one every 0.75s from anywhere in the run, for no stamina and one belt wear each. Release to stop, and shafts already flying still land.", "Wardcry, Snuff, Sounding, Threshold and Temper are inscribed permanently and attuned one at a time at the forge Sigils bench. Casting spends stamina and starts a long cooldown, read on a dial with a cast bar; kills refund it through Spell Focus and Warden's Vigil, capped at a fifth per kill, and it runs half speed while hunted. Stones drop from the King, vaults and chests, never a duplicate.", "The forge right column is tabbed (Recipes, Repairs, Sigils), each badged when it wants you. New Wardstone gem, Graven and of the Vigil affixes, and a Warden's Vigil upgrade feed Spell Focus. Touch gains Throw, Hold Call and Sigil buttons that only appear when they would do something.", "Every held sprite is redrawn with one hand language, per-shield models, a dedicated casting stone and an open retrieval hand; icons, projectiles, pickups and wards match, and held weapons recolor by material.", "Also fixed: entering town crashing after a material was added, sigils shipping with no bench to inscribe them and placeholder icons, hurling a shaft swinging the melee weapon, and point-blank throws refunding themselves at your feet. Old saves keep everything."] },
  { n: 41, hash: "0e5e0a0e020c83133e9d7deef2a15e855f386bfe", short: "0e5e0a0", date: "2026-09-13", title: "One good parry answers the whole pack", summary: "Turning a melee blow aside now leaves you untouched for 0.75s (1.25s on Normal) while every other adjacent attacker reels for at least a quarter second \u2014 no more dying to the second spear in a pile-on you already parried. The reflection lingers as well, catching one more bolt stacked behind the first, so even the King's volley can lose two bolts to a single guard.", tags: ["combat"] },
  { n: 40, hash: "37ac1da915b2391535d266d484a272dec1ad9a54", short: "37ac1da", date: "2026-09-13", title: "The new ground settles in: water, heat, honest walls", summary: "The Sunken Catacombs run with shallow water that splashes underfoot, the Emberworks breathe heat from a glowing roof, and every wall finally wears its own stone \u2014 no more crypt masonry doing double duty in the frost and the deep. Frost floors favor frost blood and turn fire away, ember floors return the courtesy, secret marks read the same everywhere, and stairs take you with a single step.", tags: ["art", "audio", "dungeon"], also: ["f11fdc6", "f78b022", "7168790", "13df300", "ddbdca5", "e47e41c", "a6a356a", "1f42ef1"], details: ["Catacombs floors carry shallow water: footfalls become splashes, and wading is audible before it is visible.", "Emberworks ceilings glow hot; the Frost Vault and the Catacombs have dedicated wall sets, and the mines lost a repeated ceiling beam.", "Frost floors favor frost creatures and never spawn fire; ember floors favor fire and never spawn frost.", "Sporegrove replaces the Glowing Warrens in the rotation \u2014 old Warrens saves still load.", "The Burrows roof is the floor you descended from, packed earth on depth 1, and bumping the stairs descends in one step."] },
  { n: 39, hash: "5543ba600bdba6fb7c1888097be92452a938b618", short: "5543ba6", date: "2026-09-13", title: "New ground under your feet, and monsters you can read", summary: "The road down is not the same road every run: five new places \u2014 the Sunken Catacombs, the Vermin Burrows, the Frost Vault, the Emberworks and the Sporegrove \u2014 pick themselves from your seed, each with its own stone, its own light and its own residents. Four hooded archers wait in them, and the colour of the arrowhead is the damage it deals: ember, rime, gloom and dawn. The Drowned Bones, the Tunnel Stalker, the Icebound Guard and the Spore Hunter keep them company. And every creature in the dungeon now tells you before it swings \u2014 weapons come up higher, mouths open wider, casters gather the shot in front of them, and shieldbearers bring the guard across their chest instead of up under their chin. Watch for it. The Ashen Throne is still the Ashen Throne.", tags: ["art", "combat", "dungeon"], also: ["99cf392", "7787a7e", "fdba9fe", "5b09d0d", "336612e", "8657990", "c6d482d", "078575e"], details: ["Depths 1\u20135 choose a biome from your run seed. Each has its own walls, floors, lighting and favoured monsters \u2014 the Burrows crawl, the Frost Vault guards, the Emberworks burn. Depth 6 is unchanged.", "Ember, Rime, Gloom and Dawn Archers: four robes, four arrowheads, four damage types. Each is soft to the element that answers it \u2014 fire quenches in frost, holy light scatters gloom.", "Drowned Bones swing slow and heavy in the shallows. Tunnel Stalkers bite and vanish. Icebound Guards freeze a shield to the arm \u2014 bring fire. Spore Hunters open a mushroom cap full of teeth.", "Every attack is drawn to be seen coming: the weapon goes up, the body throws itself at you when the blow lands, and it is standing again before it can swing next. A creature knocked out of its wind-up no longer finishes the swing it lost.", "Archers of every kind now carry and draw the same bow, so ranged is a thing you recognise across a dark room rather than six separate shapes."] },
  { n: 38, hash: "652132bbb0edc6b158f4c5be4780624b784831b9", short: "652132b", date: "2026-09-13", title: "Pick your poison: Normal and Hard", summary: "The dungeon comes in two strengths now. Hard is the game you already know — nothing about it moved, and your old saves carry on exactly where they were, on Hard. Normal hits softer and falls faster, traps sting less, you mend more, and drops are slightly kinder; same dungeon, same rules. A new save asks which one you want before it starts, on Hard unless you say otherwise; after that you switch between delves behind the new gear in town — where your cloud saves moved too — and never mid-delve, so a bad boss fight cannot be softened halfway.", tags: ["combat", "dungeon", "saves", "town"], also: ["f385a88", "7881478", "7486c03", "9cb0b7e", "97ed688", "3869c7a", "c1066b7"] },
  { n: 37, hash: "52a17bf82ff18c31e267545203a06417718e5279", short: "52a17bf", date: "2026-09-13", title: "Bones for every body, and idols where you can find them", summary: "The dungeon makes a little more sense now: everything with a body drops bones, skeletons most of all, and bats carry leather instead of rat hides they never had. The guild will get its due too — goblins lift twice as many bone idols, ghouls carry more chalices, and urns and chests hide valuables more often.", tags: ["docs", "dungeon"] },
  { n: 36, hash: "00408a1b09ca5a0922770ef5a4fc0855a94f2165", short: "00408a1", date: "2026-09-13", title: "Sort your pack mid-delve, and swap with the pile", summary: "No more closing the loot to make room: the pile opens beside your backpack now, with a Sort button on both, so a full pack is a swap instead of a dilemma — drop the old onto the pile, take the new.", tags: ["dungeon"] },
  { n: 35, hash: "b3ede350b61845e8a3b9fa6f9f2bb8573fab9262", short: "b3ede35", date: "2026-09-13", title: "Name your saves, and delete the dead ones", summary: "Your slots are yours now: name each save whatever you like — anything unnamed just reads Slot 1, Slot 2, Slot 3 — and delete a run outright when you are done with it, on this device and in the cloud. Deleting asks twice. There is no undo.", tags: ["saves"] },
  { n: 34, hash: "ccc633678d2784ea256c1aa1bcdde2f78b14ad85", short: "ccc6336", date: "2026-09-13", title: "Sell valuables in one press, and mark what the guild wants", summary: "Cashing in is easier and safer: one button on the market screen sells every valuable you own — the idols and chalices that were only ever coin — and anything a guild contract still needs wears a gold outline with a pennant, so you will know what you are giving up before you sell it.", tags: ["core"], also: ["e46dd4d"] },
  { n: 33, hash: "90ff9b3087ab6925c4ac3d061805614c30fb6d8a", short: "90ff9b3", date: "2026-09-13", title: "The King is done going easy on you", summary: "Delvers coming back from depth 6 all tell the same story: the throne room feels different, and whatever you packed last time was not enough. Pack more.", tags: ["art", "audio", "combat", "docs", "dungeon", "saves"] },
  { n: 32, hash: "182525bbaaea073858b612feb8597c49db3d3024", short: "182525b", date: "2026-09-13", title: "Make unidentified gear unusable, and point each scroll at one find", summary: "A strange blade is just a strange blade until someone names it: unidentified gear can no longer be worn and lends you nothing, not even its edge, until a scroll or the appraiser says what it is. And a Scroll of Identify no longer spends itself on the first mystery in your pack — read it, point at…", tags: ["dungeon"] },
  { n: 31, hash: "6cdf3ff857f35c868503c27bb034447ea2b666bf", short: "6cdf3ff", date: "2026-09-13", title: "Add patch notes scroll on the title screen, Prepare To Die edition line", summary: "Patch notes live on the title screen now — hit the scroll in the corner for every change, newest first. And yes: this era of the game is officially the Prepare To Die edition.", tags: ["core"] },
  { n: 30, hash: "fb6bb03cc775f9481fd2caa0099040f336a5db20", short: "fb6bb03", date: "2026-09-13", title: "Put the monsters back on the player's power curve", summary: "The dungeon pushes back now — monsters ride the same power curve you do, so shiny gear stops auto-winning past depth 2, and loot runs scarcer. Every trip down matters. Deep runs, deep consequences.", tags: ["combat", "dungeon", "saves", "town"], details: ["Monsters grow with the floor number now, not just past their own front door — health climbs fastest, damage and armor trail behind. Deep floors are long fights, not coin flips.", "Armor cannot switch damage off: your blows always land at least a third through plate, and monster armor got wide enough to be a slope instead of a wall. Elements only half-ignore armor now.", "About a third fewer monsters per floor — fights last 3–7 swings instead of one, so the same crowd would be a queue. The Cave Spider’s lunge finally reads.", "Stamina returns at 22/s after 0.9s (was 34/s after half a second). Every swing is budgeted — Fight Milk’s numbers moved with it.", "Chests in 12% of ordinary rooms (was 35%), eight or nine lootable things a floor (was nineteen). Vaults and secret rooms pay full — the two places that are supposed to.", "Healing mends, never resets: Draughts 25%, Greater 55%, shrine fonts 60% plus your stamina back.", "The starting pack is 12 slots, not 16 — sixteen never filled, which had quietly deleted the whole “what do I carry home” game. Old saves lose nothing: overflow waits in the stash.", "Pack Mule 3/6/11, Supply Crate 5/11/18, Treasure Sense +20% a rank at 6/13/22 — priced on measured value. Find finally buys better loot, not more junk: it shrinks the Common pile and reaches chest valuables and gems. Fight Milk is found-only — the merchant’s shelf is dry."] },
  { n: 29, hash: "fb51f59dc6e4e9edfbb10960f9e6f22fcbf7c222", short: "fb51f59", date: "2026-09-12", title: "ashen king bestiary update", summary: "He is home: the ASHEN KING waits on depth 6. Bring everything.", tags: ["combat"] },
  { n: 28, hash: "fa0420d8d1f755df4e0137823e840179f05daa06", short: "fa0420d", date: "2026-09-12", title: "Say it in words, and in numbers when you hold Shift", summary: "Relics talk plain now — hold Shift (or tap on touch) when you want the raw numbers. The codex shows both at once.", tags: ["combat", "docs"], also: ["48357f5"] },
  { n: 27, hash: "2700d73d614e864ead4d688728334035594b59ba", short: "2700d73", date: "2026-09-12", title: "Unlock a relic when you hold it, name it when it is appraised", summary: "Finding a relic is not knowing it — it counts the moment you grab it, but the appraiser has to name it before the codex opens its page. Mystery lump stays mysterious.", tags: ["combat", "docs", "dungeon", "saves"] },
  { n: 26, hash: "ecc90cbfc658fa036821583216074fba9f746222", short: "ecc90cb", date: "2026-09-12", title: "Give the hollow knight the same shield and guard", summary: "The Hollow Knight guards now too. Same rules as the rest: respect the raise.", tags: ["art", "combat", "docs"] },
  { n: 25, hash: "3d8fb824e9a61b08e70164ec98fb6f79d52fa24e", short: "3d8fb82", date: "2026-09-12", title: "Give shields a readable guard rhythm plus a block pose", summary: "Shield enemies telegraph now: watch the raise — swing into it and you will eat a bash and a stun. Chip the hold three times and their guard sags open.", tags: ["art", "combat", "docs", "dungeon"] },
  { n: 24, hash: "12b96d9ae335ed9f03d50c45d32f271a56a9952b", short: "12b96d9", date: "2026-09-12", title: "Nine named relics, all telling you exactly what they do", summary: "Nine named relics replace random legendaries — a sword that never dulls, a dagger that banks parries, a shield that throws hits back, a lamp that is a terrible shield, plate that eats half your healing, and one you DRINK — every one of them in real numbers, with no flowery guessing.", tags: ["combat", "docs", "dungeon", "saves"], also: ["4ff430f"] },
  { n: 23, hash: "c988bbd361b4725e56dfce6dce98ad7545a5cc31", short: "c988bbd", date: "2026-09-12", title: "New faces that punish button-mashing", summary: "Goblin archers open up from range, and shieldbearers shrug off 75% of everything from the front — flank them, time them, or back off. And something warm and angry haunts depth 3: the Ember Wisp burns and hates the frost.", tags: ["art", "combat", "docs", "dungeon"], also: ["2429c17"] },
  { n: 22, hash: "953e22c9c39b1b09c5b1acf5a4bfd141f0689963", short: "953e22c", date: "2026-09-12", title: "The bestiary keeps your grudges", summary: "There is a bestiary now: kills earn names, field notes drop off the creature they describe, and full entries spill resistances — and the codex keeps your grudges, with kills, deaths, and your biggest hit per creature.", tags: ["art", "combat", "docs", "dungeon", "saves"], also: ["75122c1"] },
  { n: 21, hash: "92ddc6068017ba49728c83444ac9493916e32e36", short: "92ddc60", date: "2026-09-12", title: "Fill out the bestiary and turn the typecheck back on", summary: "New blood: cave bats swarm the shallows (bring something slashy), and a rotting champion with a maul holds depths 5–6 (bring a mace, trust us).", tags: ["art", "combat", "docs", "town"] },
  { n: 20, hash: "293d4837a75739430556cd7b9f879e647dc13d49", short: "293d483", date: "2026-09-12", title: "Weapons with personalities, and damage with a triangle", summary: "Every weapon has a personality now — quick blades, heavy hafts, a long spear — inside a blunt-slash-pierce triangle where the right tool matters. Daggers are the crit weapon: 2.4x crits that grow with the metal. And no more free swings on an empty bar.", tags: ["audio", "combat", "docs", "dungeon", "town"], also: ["0a27ba4", "3f298b1"] },
  { n: 19, hash: "b1a1b52b1d33b0ce2e5304cc6046bd0972088970", short: "b1a1b52", date: "2026-09-12", title: "Order gear into power lines and make strong blueprints rare", summary: "Gear runs in power lines now — every base beats the last one forged two metals better — and the strong blueprints are properly rare. Chase the ladder.", tags: ["docs", "town"] },
  { n: 18, hash: "7e05c19d6065f418fd9a12f3bf8d59d5690e5607", short: "7e05c19", date: "2026-09-12", title: "Make Rock and Stone a mining pick secret", summary: "Rumor: the mining pick hides a secret. Rock and Stone, miner.", tags: ["art", "docs", "dungeon"] },
  { n: 17, hash: "3e885db849c44c529dcef0b2db5cd88df69762f1", short: "3e885db", date: "2026-09-12", title: "Stack blueprints and redraw mining pick", summary: "Blueprints stack now instead of clogging your stash, and the mining pick got a fresh look.", tags: ["art", "saves"] },
  { n: 16, hash: "772acc03bda6bc6c5dd90b1c5c9a998491ec64b6", short: "772acc0", date: "2026-09-12", title: "Polish forge progression and mobile saves", summary: "Endgame materials hit way harder — star iron, dragon scale, moonsilver, the lot — and a new Sunstone gem feeds holy builds. Forging high-tier finally pays.", tags: ["docs", "saves", "town"] },
  { n: 15, hash: "bf6ef58c851ce8f8cc7828193cac1fd4e5f04101", short: "bf6ef58", date: "2026-09-12", title: "Rebalance loot and make blueprints master recipes", summary: "Loot got rebalanced and blueprints are master recipes now: spare copies feed mastery all the way to Rank 5 instead of gathering dust.", tags: ["docs", "dungeon", "saves", "town"], details: ["Blueprints are master recipes: feed spares into a recipe to climb Ranks 1→5 for +8%, +16%, +26%, +40% core stats and tougher gear. Unlocking costs 1 blueprint; each next rank costs its number.", "Secondary forge slots pull weight now — metal stiffens, wood quickens, hide heartens, cloth endures, bone brutalizes, all scaling with tier.", "Forged rarity follows the metal, up to 4 affixes on the finest pieces — a Master Smith squeezes out one more.", "Loot unlocks one band every two depths: Rare from 2, Epic from 4, Legendary at 6 only. High-tier metals and gems arrive later too.", "Blueprint drops chase recipes you have not learned and stop once one is maxed — no more dead drops.", "Vaults and secret rooms still pay, but the second guaranteed piece is rarer (50%→25%) and their gear rolls at your depth, not above it."] },
  { n: 14, hash: "68556c243f5d4541293dbd557e51ec7955d19a4e", short: "68556c2", date: "2026-09-12", title: "Accounts, three save slots, and cloud saves that ask first", summary: "Your delves follow you now: optional email accounts, three save slots, and background cloud sync — and when two devices disagree, YOU pick the winner, never mid-delve, never silently.", tags: ["saves"], also: ["69da1ca", "b1a022e"] },
  { n: 13, hash: "3df228d2f3a3110f2096913eebc8b3b2754adc3f", short: "3df228d", date: "2026-09-12", title: "Sprung traps leave wreckage, and it stays", summary: "Dead traps stay on the floor as wreckage — bent plates, collapsed spikes, shattered wards. You will remember where you have been.", tags: ["art", "docs", "dungeon"] },
  { n: 12, hash: "d325893713aeae706386483424f881d81ba1afd8", short: "d325893", date: "2026-09-12", title: "Add the mining pick", summary: "New weapon: the mining pick. Quick for its punch with a taste for crits — and the forge knows its recipe.", tags: ["art", "dungeon", "town"] },
  { n: 11, hash: "5871a6356366f0955ab15f92a279f38cf7320a3c", short: "5871a63", date: "2026-09-12", title: "Add durability: gear wears where it is used, the forge mends it", summary: "Your gear wears down fighting: weapons dull on every landed blow, shields soak what you block, armour suffers what gets through. Broken gear still fights at quarter strength, and the forge mends the lot — broken first — with one Mend All button.", tags: ["docs", "dungeon", "town"] },
  { n: 10, hash: "7b3bfeacb9f7092fcc24fda58a9465570d4c22de", short: "7b3bfea", date: "2026-09-12", title: "Shrines in three flavours, and curses to answer them", summary: "Three shrines now, readable from across the room: blue font heals you clean and lifts curses, violet idol gambles blessings against curses that follow you all run, gold stone sells blessings for coin up front. Feeling lucky?", tags: ["art", "docs", "dungeon", "saves"] },
  { n: 9, hash: "32ff6d1e55a466004e36b25f9f7fb37999f0f825", short: "32ff6d1", date: "2026-09-12", title: "Some chests are lying to you", summary: "Some chests are lying to you — learn the tell before you reach. When one unfolds its spindly legs it hits like a vault guardian, so make sure the hoard is worth it.", tags: ["art", "combat", "docs", "dungeon", "saves"], also: ["d29dc2b"] },
  { n: 8, hash: "d46a8eebe7ec822f7fa6a0abd68dbb0a0d109de6", short: "d46a8ee", date: "2026-09-12", title: "Make traps readable, stop loot stealing the tap, close the renown loop", summary: "Traps glint cold iron now so your eyes stand a chance, loot stops hijacking your taps mid-brawl, and chickening out at depth 1 pays exactly nothing. No more free renown.", tags: ["art", "docs", "dungeon"] },
  { n: 7, hash: "667f68cb073f3b5952b2b81c2c6d20b93aae18cc", short: "667f68c", date: "2026-09-12", title: "Add Lantern Wick: buy a little more light", summary: "Hate the dark? The Warden sells lamplight now: three ranks of Lantern Wick stretch your torch further, and the first rank spots traps a tile sooner.", tags: ["docs", "dungeon"] },
  { n: 6, hash: "0dc7f001819db3f780cf8b804bb6e5cf6d543dbf", short: "0dc7f00", date: "2026-09-12", title: "Add parries: deny the hit, stagger melee, reflect bolts", summary: "Parrying is in! Snap your guard up at the last instant and the hit fizzles — zero damage, zero stamina — while melee attackers reel for a full second of double damage. Even arrows: smack them back into whoever shot them.", tags: ["audio", "combat", "docs", "dungeon", "saves"] },
  { n: 5, hash: "ca998450a2477291d6988bd4ca365aacc2523d5e", short: "ca99845", date: "2026-09-12", title: "Rework the first-person hand, fix the knight's floating sword", summary: "Your hand looks like a hand now — fingers, bracer, the works — and the Hollow Knight finally holds his sword instead of wearing it through the chest. The title screen lists the real controls too.", tags: ["art", "combat", "dungeon"] },
  { n: 4, hash: "0dacefdcfe1255944e0a41104464065e6585e460", short: "0dacefd", date: "2026-09-12", title: "Town portals, packing from the stash, and free the boss hoard", summary: "Recall scrolls do not end your run anymore — they rip open a two-way portal home. Bank your gold, restock, then step back to the exact depth you left. Pack your bag from the stash before you descend, and the boss hoard finally drops where you can grab it.", tags: ["art", "docs", "dungeon", "saves"] },
  { n: 3, hash: "741429975e57f1d900f9eab30faa0c7b654c78ac", short: "7414299", date: "2026-09-12", title: "Add traps: dart plates, spike pits and alarm wards", summary: "The floor fights back: dart plates, spike pits, and alarm wards that scream every monster in earshot toward you. Walk slow, watch the ground, pry up what you spot for free salvage — and lure chasers onto the spikes you already found.", tags: ["art", "docs", "dungeon", "saves"] },
  { n: 2, hash: "be7fac0bb094e50cf45c40676d385739dfaaf4fb", short: "be7fac0", date: "2026-09-11", title: "The game fits in your pocket", summary: "Phone players, you are in: compact layout, installable to your home screen, drag-anywhere movement with one smart button that swings when there is something to hit and grabs when there is something to take. And nobody heals by standing around — bring supplies or do not bleed.", tags: ["combat", "docs", "dungeon", "mobile", "saves"], also: ["63a3a34", "4218a74"] },
  { n: 1, hash: "7147fc8c66166737c4101c79bb1af60d6280a1db", short: "7147fc8", date: "2026-09-11", title: "Overhaul: PS1 renderer, real-time combat, loot economy, pixel art", summary: "Everything is new. First-person dungeon crawling with real-time combat — read the wind-up, dodge or block — torchlight and fog, six floors, a boss at the bottom, and a full loot loop of market, forge and contracts. All in crunchy PS1 pixel art.", tags: ["art", "audio", "combat", "docs", "dungeon", "saves", "town"] },
];

export const PATCH_COUNT = PATCHES.length;
